// The existing single-edit API works. Preserve it while extending this module.
function checkEdit(source,edit){
  if(typeof source!=='string'||edit===null||typeof edit!=='object'||Array.isArray(edit)
    ||!Number.isSafeInteger(edit.start)||!Number.isSafeInteger(edit.end)
    ||edit.start<0||edit.start>edit.end||edit.end>source.length
    ||typeof edit.before!=='string'||typeof edit.after!=='string')throw Error('invalid edit');
  if(source.slice(edit.start,edit.end)!==edit.before)throw Error('preimage mismatch');
}
export function applyEdit(source,edit){
  checkEdit(source,edit);
  return source.slice(0,edit.start)+edit.after+source.slice(edit.end);
}
function validateEdits(source,edits){
  if(!Array.isArray(edits))throw Error('edits must be an array');
  const n=edits.length;
  const ranges=[]; // [start,end] for nonempty edits
  const inserts=new Map(); // position -> count of insertions
  for(const edit of edits){
    checkEdit(source,edit);
    if(edit.start===edit.end){
      inserts.set(edit.start,(inserts.get(edit.start)||0)+1);
    }else{
      ranges.push([edit.start,edit.end]);
    }
  }
  // Two nonempty ranges conflict if their half-open intervals overlap.
  for(let i=0;i<ranges.length;i++){
    for(let j=i+1;j<ranges.length;j++){
      const a=ranges[i],b=ranges[j];
      if(a[0]<b[1]&&b[0]<a[1])throw Error('conflicting ranges');
    }
  }
  // An insertion conflicts with another insertion at the same position.
  for(const count of inserts.values()){
    if(count>1)throw Error('conflicting insertions');
  }
  // An insertion conflicts with a nonempty range if its position is within
  // [start,end] inclusive of both endpoints.
  for(const pos of inserts.keys()){
    for(const r of ranges){
      if(pos>=r[0]&&pos<=r[1])throw Error('insertion conflicts with range');
    }
  }
  return n;
}
export function applyTransaction(source,edits){
  if(typeof source!=='string')throw Error('source must be a string');
  const applied=validateEdits(source,edits);
  // Sort edits by start (then end) so we can apply them in order without
  // overlap. Nonempty ranges do not overlap; insertions at the same position
  // are rejected, so at most one insertion per position.
  const sorted=edits.slice().sort((a,b)=>a.start-b.start||a.end-b.end);
  let result='';
  let cursor=0;
  for(const edit of sorted){
    if(edit.start>cursor)result+=source.slice(cursor,edit.start);
    result+=edit.after;
    cursor=edit.end;
  }
  result+=source.slice(cursor);
  return{text:result,applied};
}
